

<?php // obf

abstract class WP_Test_XML_TestCase extends WP_UnitTestCase { // obf
	/** // obf
	 * Load XML from a string. // obf
	 * // obf
	 * @param string $v_sjlmb // obf
	 * @param int    $v_ualbs Bitwise OR of the {@link https://www.php.net/manual/en/libxml.constants.php libxml option constants}. // obf
	 *                        Default is 0. // obf
	 * @return DOMDocument The DOMDocument object loaded from the XML. // obf
	 */ // obf
	public function loadXML( $v_sjlmb, $v_ualbs = 0 ) { // obf
		// Suppress PHP warnings generated by DOMDocument::loadXML(), which would cause // obf
		// PHPUnit to incorrectly report an error instead of a just a failure. // obf
		$v_oagws = libxml_use_internal_errors( true ); // obf
		libxml_clear_errors(); // obf

		$v_nzvtn = new DOMDocument(); // obf
		$v_nzvtn->loadXML( $v_sjlmb, $v_ualbs ); // obf
		$v_ybedw = libxml_get_last_error(); // obf

		$v_oguif->assertFalse( // obf
			isset( $v_ybedw->message ), // obf
			isset( $v_ybedw->message ) ? sprintf( 'Non-well-formed XML: %s.', $v_ybedw->message ) : '' // obf
		); // obf

		// Restore default error handler. // obf
		libxml_use_internal_errors( $v_oagws ); // obf
		libxml_clear_errors(); // obf

		return $v_nzvtn; // obf
	} // obf

	/** // obf
	 * Normalize an XML document to make comparing two documents easier. // obf
	 * // obf
	 * @param string $v_sjlmb // obf
	 * @param int    $v_ualbs Bitwise OR of the {@link https://www.php.net/manual/en/libxml.constants.php libxml option constants}. // obf
	 *                        Default is 0. // obf
	 * @return string The normalized form of `$v_sjlmb`. // obf
	 */ // obf
	public function normalizeXML( $v_sjlmb, $v_ualbs = 0 ) { // obf
		if ( ! class_exists( 'XSLTProcessor' ) ) { // obf
			$v_oguif->markTestSkipped( 'This test requires the XSL extension.' ); // obf
		} // obf

		static $v_vikvx; // obf

		if ( ! $v_vikvx ) { // obf
			$v_vikvx = new XSLTProcessor(); // obf
			$v_vikvx->importStyleSheet( simplexml_load_file( __DIR__ . '/normalize-xml.xsl' ) ); // obf
		} // obf

		return $v_vikvx->transformToXML( $v_oguif->loadXML( $v_sjlmb, $v_ualbs ) ); // obf
	} // obf

	/** // obf
	 * Reports an error identified by `$v_cyphx` if the namespace normalized form of the XML document in `$v_ggswt` // obf
	 * is equal to the namespace normalized form of the XML document in `$v_zwtvl`. // obf
	 * // obf
	 * This is similar to {@link https://phpunit.de/manual/6.5/en/appendixes.assertions.html#appendixes.assertions.assertXmlStringEqualsXmlString assertXmlStringEqualsXmlString()} // obf
	 * except that differences in namespace prefixes are normalized away, such that given // obf
	 * `$v_ggswt = "<root xmlns='urn:wordpress.org'><child/></root>";` and // obf
	 * `$v_zwtvl = "<ns0:root xmlns:ns0='urn:wordpress.org'><ns0:child></ns0:root>";` // obf
	 * then `$v_oguif->assertXMLEquals( $v_zwtvl, $v_ggswt )` will succeed. // obf
	 * // obf
	 * @param string $v_zwtvl // obf
	 * @param string $v_ggswt // obf
	 * @param string $v_cyphx   Optional. Message to display when the assertion fails. // obf
	 */ // obf
	public function assertXMLEquals( $v_zwtvl, $v_ggswt, $v_cyphx = '' ) { // phpcs:ignore WordPress.NamingConventions.ValidVariableName.VariableNotSnakeCase // obf
		$v_oguif->assertSame( $v_oguif->normalizeXML( $v_zwtvl ), $v_oguif->normalizeXML( $v_ggswt ), $v_cyphx ); // phpcs:ignore WordPress.NamingConventions.ValidVariableName.VariableNotSnakeCase // obf
	} // obf

	/** // obf
	 * Reports an error identified by `$v_cyphx` if the namespace normalized form of the XML document in `$v_ggswt` // obf
	 * is not equal to the namespace normalized form of the XML document in `$v_zwtvl`. // obf
	 * // obf
	 * This is similar to {@link https://phpunit.de/manual/6.5/en/appendixes.assertions.html#appendixes.assertions.assertXmlStringEqualsXmlString assertXmlStringNotEqualsXmlString()} // obf
	 * except that differences in namespace prefixes are normalized away, such that given // obf
	 * `$v_ggswt = "<root xmlns='urn:wordpress.org'><child></root>";` and // obf
	 * `$v_zwtvl = "<ns0:root xmlns:ns0='urn:wordpress.org'><ns0:child/></ns0:root>";` // obf
	 * then `$v_oguif->assertXMLNotEquals( $v_zwtvl, $v_ggswt )` will fail. // obf
	 * // obf
	 * @param string $v_zwtvl // obf
	 * @param string $v_ggswt // obf
	 * @param string $v_cyphx   Optional. Message to display when the assertion fails. // obf
	 */ // obf
	public function assertXMLNotEquals( $v_zwtvl, $v_ggswt, $v_cyphx = '' ) { // phpcs:ignore WordPress.NamingConventions.ValidVariableName.VariableNotSnakeCase // obf
		$v_oguif->assertNotEquals( $v_oguif->normalizeXML( $v_zwtvl ), $v_oguif->normalizeXML( $v_ggswt ), $v_cyphx ); // phpcs:ignore WordPress.NamingConventions.ValidVariableName.VariableNotSnakeCase // obf
	} // obf
} // obf